# Friendlier error messages for students. Do not edit this file.

import pytest

HINTS = [
    ["local variable",
     "Your function changes a global variable without saying so.\n"
     "Add this line at the top of the function:\n"
     "    global Stack, TopOfStack"],

    ["index out of range",
     "You used an index outside the array.\n"
     "  - Did you fill Stack with 10 elements (all -1) at the start?\n"
     "  - Does Push check if the stack is full BEFORE adding 1 to TopOfStack?"],

    ["can only concatenate str",
     "You tried to join a string and a number with +.\n"
     "Is Pop() returning -1 because the stack is empty? Stop popping when\n"
     "IsEmpty() is True."],

    ["'NoneType' object",
     "Something is None (nothing). A function probably forgot to 'return'\n"
     "its answer, or you left 'pass' in it."],
]


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
    outcome = yield
    report = outcome.get_result()
    if report.when != "call" or not report.failed or call.excinfo is None:
        return
    message = str(call.excinfo.value)
    for hint in HINTS:
        if hint[0] in message:
            report.sections.append(["HINT", hint[1]])
            return


def pytest_assertrepr_compare(op, left, right):
    if op == "==" and left is None:
        return [
            "Your function returned None (nothing).",
            "",
            "This almost always means one of two things:",
            "  1. You left 'pass' in the function instead of writing code.",
            "  2. You wrote the code but forgot the 'return' statement.",
            "",
            "The test expected: " + repr(right),
        ]
    return None
